// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let arcs, nArcs, pFactor;
let palette = ["#ebedec", "#71859d", "#f6d448", "#fafafa"];

let N_FRAMES = 100, gradientArc = true;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB);

  background(5);
}

function draw() {
  if ((frameCount - 1) % N_FRAMES == 0) {
    pFactor = random(0.55, 0.7);
    let thetaDivs = random([4, 6]);
    let theta0 = ~~random(thetaDivs)*TAU/thetaDivs;
    arcs = [];
    subdivide(width/2, height/2, 50, 200, theta0, theta0+TAU, 2);
    nArcs = arcs.length;
    shuffle(arcs, true);
  }

  /*
  let t = 3.5*(frameCount%N_FRAMES)/N_FRAMES;
  if (t > 1.5) t = 3-t;
  t = easeInOutExpo(constrain(t, 0, 1));
  */

  //let t = easeInExpo(constrain(2*(frameCount%N_FRAMES)/N_FRAMES, 0, 1));

  let phase1 = N_FRAMES/3;
  //let phase2 = N_FRAMES - phase1;

  let animUnit = phase1/nArcs;
  let f = frameCount%N_FRAMES;
  let i = 0;

  for (let a of arcs) {
    var t;
    if (f < animUnit*i) t = 0;
    else if (f < animUnit*i + phase1) t = easeOutExpo((f-animUnit*i)/phase1);
    else t = 1;

    if (t > 0.01) drawArc(a.x0, a.y0, a.r1, a.r2, a.theta1, a.theta1 + t*(a.theta2-a.theta1), a.col);
    i++;
  }
}

function mouseClicked() {
	gradientArc = !gradientArc;
}

function subdivide(x0, y0, r1, r2, theta1, theta2, p) {
  let eventualRadiusDivs = [2, 3, 3, 4, 4, 6];
  let possibleRadiusDivs = [];
  for (let e of eventualRadiusDivs) {
    if ((r2-r1)/e > 10 + randomGaussian(0, 2)) possibleRadiusDivs.push(e);
  }
  let rl = possibleRadiusDivs.length;

  let eventualThetaDivs = [2, 3, 3, 4, 4, 6];
  let possibleThetaDivs = [];
  for (let e of eventualRadiusDivs) {
    if ((theta2-theta1)/e > PI/20 + randomGaussian(0, PI/80)) possibleThetaDivs.push(e);
  }
  let tl = possibleThetaDivs.length;

  if ((rl == 0 && tl == 0) || random() > p) {
    arcs.push({
      x0: x0,
      y0: y0,
      r1: r1,
      r2: r2,
      theta1: theta1,
      theta2: theta2,
      col: random(palette)
    });
    return;
  }

  if ((rl == 0) || (rl > 0 && tl > 0 && random() < tl/(rl+tl))) {
    // subdivide through the angle
    let nDivs = random(possibleThetaDivs);
    let thetaStep = (theta2-theta1)/nDivs;
    for (let i = 0; i < nDivs; i++) {
      subdivide(x0, y0, r1, r2, theta1 + i*thetaStep, theta1 + (i+1)*thetaStep, p*pFactor);
    }
  } else {
    // subdivide through the radius
    var nDivs = random(possibleRadiusDivs);
    let rStep = (r2-r1)/nDivs;
    for (let i = 0; i < nDivs; i++) {
      subdivide(x0, y0, r1 + i*rStep, r1 + (i+1)*rStep, theta1, theta2, p*pFactor);
    }
  }
}

function drawArc(x0, y0, r1, r2, theta1, theta2, col) {
	if (gradientArc) {
		noFill();
		let h = hue(window.color(col)), s = saturation(window.color(col)), b = brightness(window.color(col));
		for (let r = r1+1; r < r2-1; r+=0.5) {
			stroke(h, s, b-map(r, r1, r2, -8, 8));
			arc(x0, y0, 2*r, 2*r, theta1, theta2);
		}

		stroke(5);
		var thetaStep = TAU/100;
		beginShape();
		for (let theta = theta1; theta < theta2; theta += (Math.max(0.001, Math.abs(thetaStep)) || 1)) {
			let x = x0 + r2*cos(theta);
			let y = y0 + r2*sin(theta);
			vertex(x, y);
		}
		var x = x0 + r2*cos(theta2);
		var y = y0 + r2*sin(theta2);
		vertex(x, y);
		for (let theta = theta2; theta > theta1; theta -= thetaStep) {
			var x = x0 + r1*cos(theta);
			var y = y0 + r1*sin(theta);
			vertex(x, y);
		}
		x = x0 + r1*cos(theta1);
		y = y0 + r1*sin(theta1);
		vertex(x, y);
		endShape(CLOSE);
	} else {
		var thetaStep = TAU/100;
		stroke(5);
		fill(col);
		beginShape();
		for (let theta = theta1; theta < theta2; theta += (Math.max(0.001, Math.abs(thetaStep)) || 1)) {
			var x = x0 + r2*cos(theta);
			var y = y0 + r2*sin(theta);
			vertex(x, y);
		}
		var x = x0 + r2*cos(theta2);
		var y = y0 + r2*sin(theta2);
		vertex(x, y);
		for (let theta = theta2; theta > theta1; theta -= thetaStep) {
			var x = x0 + r1*cos(theta);
			var y = y0 + r1*sin(theta);
			vertex(x, y);
		}
		x = x0 + r1*cos(theta1);
		y = y0 + r1*sin(theta1);
		vertex(x, y);
		endShape(CLOSE);
	}
}

// adapted from easing.net
function easeOutExpo(x) {
  return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
}

